using PharmaLIMS.TrustedSigning;
using System.Text.Json;
int checks=0;
void Check(bool value,string message){if(!value)throw new Exception(message);checks++;}
void Reject(Action f,string message){try{f();}catch(ArgumentException){checks++;return;}catch(JsonException){checks++;return;}throw new Exception(message);}
var r=new PrmRegistrationRequest { SampleCategory="Raw Material",MaterialCode="RM-01",MaterialName="Material",ManufacturerLotNo="LOT-1",SamplePurpose="Release",SpecificationNo="SPEC-01",SampledBy="Sampler",SampleDateTime=new DateTime(2026,10,28,10,30,0),SampleQuantity=1m,Unit="g" };
PrmRegistrationPolicy.Validate(r);checks++;
string json=PrmRegistrationPolicy.CanonicalPayload(r);
Check(PrmRegistrationPolicy.Parse(json)==r,"Typed payload changed after round trip");
Check(PrmRegistrationPolicy.PayloadHash(r)==PrmRegistrationPolicy.PayloadHash(PrmRegistrationPolicy.Parse(json)),"Recovery payload hash changed");
Check(PrmRegistrationPolicy.PayloadHash(r)!=PrmRegistrationPolicy.PayloadHash(r with {MaterialCode="RM-02"}),"Changed payload must change request identity");
Reject(()=>PrmRegistrationPolicy.Parse(json[..^1]+",\"CreatedBy\":\"Admin\"}"),"Payload actor accepted");
Reject(()=>PrmRegistrationPolicy.Parse(json[..^1]+",\"SampleCategory\":\"Raw Material\"}"),"Duplicate property accepted");
Reject(()=>PrmRegistrationPolicy.Parse("[]"),"Non-object accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {SampleCategory="Water"}),"Wrong module accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {SampleQuantity=0}),"Zero quantity accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {SampleQuantity=1.0001m}),"Rounded quantity accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {SampleQuantity=1000000000000000m}),"Overflow quantity accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {Unit=""}),"Missing unit accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {SpecificationNo=""}),"Missing specification accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {SampledBy=""}),"Missing sampler accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {SamplePurpose="Retest",RetestReason=""}),"Missing retest reason accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {MaterialCode=""}),"Missing item accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {SampleDateTime=DateTime.SpecifyKind(r.SampleDateTime,DateTimeKind.Utc)}),"UTC timestamp accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {SampleDateTime=r.SampleDateTime.AddTicks(1)}),"Subsecond timestamp accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {ReceivedDate=r.SampleDateTime}),"Time in date-only field accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {Remarks=new string('x',1001)}),"Oversize remarks accepted");
Reject(()=>PrmRegistrationPolicy.Validate(r with {MaterialName="Material\0"}),"Control character accepted");
var production=r with {SampleCategory="Production / In-Process",ProductCode="PR-1",ProductName="Product",BatchNo="B1"};
Reject(()=>PrmRegistrationPolicy.Validate(production),"Missing production stage accepted");
PrmRegistrationPolicy.Validate(production with {ProductionStage="After Mixing"});checks++;
Reject(()=>PrmRegistrationPolicy.Validate(production with {SampleCategory="Stability",ProductionStage="Long Term"}),"Incomplete stability scope accepted");
const string valid="Server=tcp:AMEEN,1433;Database=EQ001_UAT_AMEEN_20261024;Integrated Security=true;Encrypt=true;TrustServerCertificate=false";
PrmRegistrationPolicy.RequireTarget(valid);checks++;
Reject(()=>PrmRegistrationPolicy.RequireTarget(valid.Replace("AMEEN,1433","OTHER,1433")),"Wrong server accepted");
Reject(()=>PrmRegistrationPolicy.RequireTarget(valid.Replace("EQ001_UAT_AMEEN_20261024","PharmaLIMS")),"Production accepted");
Reject(()=>PrmRegistrationPolicy.RequireTarget(valid.Replace("Integrated Security=true","User ID=readonly;Password=example")),"Host SQL authentication accepted");
PrmRegistrationPolicy.RequireTarget(valid.Replace("Integrated Security=true","User ID=readonly;Password=example"),requireIntegratedSecurity:false);checks++;
Reject(()=>PrmRegistrationPolicy.RequireTarget(valid.Replace("TrustServerCertificate=false","TrustServerCertificate=true")),"Unvalidated TLS accepted");
// DatePicker defaults use DateTime.Today (Local); preserve the entered wall clock, not its timezone offset.
var localSampling=DateTime.SpecifyKind(r.SampleDateTime,DateTimeKind.Local);
var localCalendar=DateTime.SpecifyKind(r.SampleDateTime.Date,DateTimeKind.Local);
var mapping=typeof(PrmRegistrationRequest).Assembly.GetType("PharmaLIMS.TrustedSigning.PrmRegistrationFormMapping");
Check(mapping is not null,"PRM UI wall-clock mapper is missing; DatePicker Local defaults cannot satisfy the strict timestamp contract");
var form=JsonSerializer.Deserialize<Dictionary<string,object?>>(json)!;
form["SampleDateTime"]=localSampling;
form["ReceivedDate"]=localCalendar;
form["RetestDate"]=null;
var capture=mapping!.GetMethod("Capture")!;
var captured=(PrmRegistrationRequest)capture.Invoke(null,new object[]{form})!;
Check(captured.SampleDateTime.Kind==DateTimeKind.Unspecified && captured.SampleDateTime.Ticks==localSampling.Ticks,"UI local sampling wall clock shifted or retained timezone authority");
Check(captured.ReceivedDate?.Kind==DateTimeKind.Unspecified && captured.ReceivedDate?.Ticks==localCalendar.Ticks,"UI calendar date shifted or retained timezone authority");
Check(captured.RetestDate is null,"UI omitted date must remain null");
Check(((DateTime)form["SampleDateTime"]!).Kind==DateTimeKind.Local,"Capture mutated the original form values");
Check(PrmRegistrationPolicy.Parse(PrmRegistrationPolicy.CanonicalPayload(captured))==captured,"Normalized UI defaults cannot survive durable recovery round trip");
Reject(()=>PrmRegistrationPolicy.Validate(r with {SampleDateTime=localSampling}),"Host accepted direct Local timestamp without UI normalization");
Console.WriteLine($"PASS: {checks} PRM registration policy checks.");
